const REVIEW=globalThis.QI_REVIEW||null;
const savedHome=REVIEW?'Saved in this browser':'Saved on Spark';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>s.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',docs:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7',data:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',meetings:'M12 3a3 3 0 013 3v6a3 3 0 01-6 0V6a3 3 0 013-3z M5 11v1a7 7 0 0014 0v-1 M12 19v3 M8 22h8',library:'M3 4h7a3 3 0 012 2 3 3 0 013-2h6v16h-6a3 3 0 00-3 2 3 3 0 00-3-2H3z M12 6v16',delivery:'M12 3v12 M7 10l5 5 5-5 M4 15v6h16v-6',pilot:'M3 17l6-6 4 3 7-10 M15 4h5v5',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',plus:'M12 4v16 M4 12h16',target:'M20 12a8 8 0 11-8-8 M17 3v4h4 M12 12l7-7 M15 12a3 3 0 11-3-3'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.docs}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const nav=[['overview','Overview'],['docs','QI documents'],['data','Data & measures'],['meetings','Meeting room'],['library','Reference library'],['delivery','Delivery & backup'],['pilot','Pilot insights']];
const S={page:'overview',data:null,project:null,role:null,doc:null,draft:null,dirty:false,saving:false,editRevision:0,meeting:null,meetingData:null,events:null,timer:null,route:'reasoning'};
let toastTimer,refreshTimer;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,method='GET',body){if(REVIEW)return REVIEW.request(path,method,body);const headers={'X-QI-Request':'1'};if(body!==undefined&&!(body instanceof FormData))headers['Content-Type']='application/json';const r=await fetch(path,{method,headers,body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});const data=await r.json().catch(()=>({detail:'Server response was not readable'}));if(!r.ok){const e=new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));e.status=r.status;e.data=data;throw e}return data}
const url=s=>`/api/projects/${encodeURIComponent(S.project)}${s}`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const art=kind=>S.data.artifacts.find(a=>a.kind===kind);
const num=n=>Number.isFinite(n)?Number(n.toFixed(1)).toLocaleString():'—';
const when=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Not yet';
function audioOnline(){const c=S.data.asr.connections?.find(c=>c.meeting===S.meeting);return c&&Date.now()-new Date(c.last_contact).getTime()<20000}
function online(){return S.data.companion&&Date.now()-new Date(S.data.companion.last_contact).getTime()<45000}
function heading(name,description,actions=''){return `<div class="heading"><div><h1>${name}</h1><p>${description}</p></div><div class="inline wrap">${actions}</div></div>`}
function shell(){return `<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">✳</span>QI Coach<span class="badge grey">PILOT</span></div><div class="project-switch"><div class="eyebrow">Your workspace</div><strong>${S.data.project.synthetic?'Synthetic clinic':esc(S.data.project.name)}</strong><span class="subtle">Small steps. Better systems.</span></div><div class="navlabel">PROJECT</div><nav class="nav" aria-label="Workspace">${nav.map(([id,label])=>btn(icon(id)+label,'nav',S.page===id?'active':'',`data-page="${id}"`)).join('')}</nav><div class="tagline">Improvement is a team practice.</div><div class="sidebar-foot"><div class="local-label"><span class="dot"></span>${REVIEW?'Browser review':'Hosted on your Spark'}</div><div class="subtle" style="font-size:10px">${REVIEW?'Synthetic data · Local edits':'Local models · Private workspace'}</div><div class="subtle" style="font-size:9px;margin-top:12px">${esc(S.role)} access</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace &nbsp; / &nbsp; <b>${nav.find(n=>n[0]===S.page)?.[1]}</b></div><div class="header-actions">${S.data.project.synthetic?badge('Synthetic demonstration','amber'):badge('Project workspace')}<span class="subtle" id="connection"><span class="dot"></span> ${REVIEW?'Browser preview':'Live updates'}</span>${REVIEW?'':btn('Sign out','logout','quiet small')}<span class="avatar">QI</span></div></header><div class="content" id="content"></div></main></div>`}
function render(){if(!S.data)return;$('#app').innerHTML=shell();$('#content').innerHTML=({overview,docs,dataView,meetings,library,delivery,pilot}[S.page==='data'?'dataView':S.page])();if(S.page==='docs'){bindEditor();if(S.lastChange===S.doc)document.querySelector('.document-editor')?.classList.add('changed')}else if(S.lastChange)document.querySelector('.content .card')?.classList.add('changed');S.lastChange=null;REVIEW?.decorate();}
async function refresh(force=false){if(!S.project)return;const data=await api(url(''));S.data=data;if(!S.meeting&&data.meetings.length)S.meeting=data.meetings[0].id;if(S.page==='meetings'&&S.meeting)S.meetingData=await api(url(`/meetings/${S.meeting}`));const focused=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(force||(!S.dirty&&!S.saving&&!focused))render();else if(S.page==='docs'){const current=data.artifacts.find(a=>a.id===S.doc);if(current&&current.revision>S.editRevision&&!S.saving){const n=$('#saveState');if(n)n.textContent='Newer revision available · your draft is preserved'}}}
function startEvents(){if(REVIEW)return;S.events?.close();S.events=new EventSource(url(`/events?after=${S.data.event_cursor}`));S.events.onmessage=event=>{const update=JSON.parse(event.data);S.lastChange=update.kind==='artifact'?update.entity:null;clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>refresh().catch(e=>toast(e.message)),350)};S.events.onopen=()=>{const c=$('#connection');if(c)c.innerHTML='<span class="dot"></span> Live updates'};S.events.onerror=()=>{const c=$('#connection');if(c)c.textContent='Reconnecting… saved work is safe'}}
function runChart(chart){const pts=chart?.run?.points||[];if(!pts.length)return '<div class="empty">Import a validated time series to create a run chart.</div>';const w=660,h=265,left=44,right=15,top=22,bottom=45,high=Math.max(...pts.map(p=>p.value))*1.2||1,x=i=>left+i*(w-left-right)/Math.max(pts.length-1,1),y=v=>h-bottom-v/high*(h-top-bottom);const median=chart.run.median;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Run chart of ${esc(chart.unit)} over time">${[0,1,2,3,4].map(i=>{const v=high*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#edf0e9"/><text x="${left-12}" y="${y(v)+3}" text-anchor="end">${num(v)}</text>`}).join('')}${median===null?'':`<line x1="${left}" x2="${w-right}" y1="${y(median)}" y2="${y(median)}" stroke="#bbaa82" stroke-dasharray="5 5"/>`}<path d="M ${x(0)} ${h-bottom} ${pts.map((p,i)=>`L ${x(i)} ${y(p.value)}`).join(' ')} L ${x(pts.length-1)} ${h-bottom} Z" fill="#dcece23b"/><polyline points="${pts.map((p,i)=>`${x(i)},${y(p.value)}`).join(' ')}" fill="none" stroke="#4b8567" stroke-width="2.4" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="3.6" fill="#fff" stroke="#4b8567" stroke-width="1.8"><title>${esc(p.date)}: ${num(p.value)} ${esc(chart.unit)} (${p.n} observations)</title></circle>${(i%Math.max(1,Math.ceil(pts.length/5))===0||i===pts.length-1)?`<text x="${x(i)}" y="${h-18}" text-anchor="middle">${esc(p.date.slice(5))}</text>`:''}`).join('')}</svg>`}
function pareto(chart){const rows=chart?.pareto||[];if(!rows.length)return '<div class="empty">A Pareto chart needs a mapped category column.</div>';const max=Math.max(...rows.map(r=>r.count));return rows.slice(0,12).map(r=>`<div class="pareto-row"><span>${esc(r.category)}</span><div class="bar-track"><div class="bar" style="width:${100*r.count/max}%" title="Cumulative ${num(r.cumulative_percent)}%"></div></div><span>${r.count}</span></div>`).join('')+`<p class="proof">Ordered by count. Cumulative percentages available on hover and in CSV exports.</p>`}
function overview(){const d=S.data.datasets[0],chart=d?.calculation?.charts,aim=art('charter')?.body,cycle=art('pdsa')?.body.cycles?.[0],actions=art('actions')?.body.items||[],latest=chart?.run.points.at(-1)?.value,imported=S.data.imports[0];return heading('Every small step moves care forward.','Your project, evidence, and next steps — in one shared workspace.',btn(icon('meetings')+'Open meeting room','nav','primary','data-page="meetings"'))+`<div class="hero"><div class="hero-icon">${icon('target')}</div><div><div class="eyebrow">OUR IMPROVEMENT AIM</div><p>${esc(aim?.aim||'Define a measurable aim to give the team a shared direction.')}</p></div>${badge('Exploring a change')}</div><div class="stats"><div class="stat"><div class="label">${icon('data')}Baseline median</div><div class="value">${num(chart?.run.median)}<span>${esc(chart?.unit||'')}</span></div><div class="subtle">First ${chart?.run.baseline_count||0} daily observations</div></div><div class="stat"><div class="label">${icon('pilot')}Latest daily mean</div><div class="value">${num(latest)}<span>${esc(chart?.unit||'')}</span></div><div class="subtle">${chart?.run.points.at(-1)?.date||'Awaiting data'} · ${S.data.project.synthetic?'synthetic data':'validated snapshot'}</div></div><div class="stat"><div class="label">${icon('check')}Next actions</div><div class="value">${actions.filter(a=>a.status!=='done').length}<span>to move forward</span></div><div class="subtle">Small, practical steps for your team</div></div></div><div class="grid"><section class="card"><div class="card-head"><div><h2>Less waiting. More learning.</h2><p>${esc(d?.name||'Time series')} · daily ${esc(chart?.aggregation||'mean')}</p></div><div class="legend"><span><i></i>Observed</span><span><i class="median"></i>Baseline</span></div></div>${runChart(chart)}<div class="chart-note">${esc(chart?.methodology.caution||'Time-ordered observations are needed.')} ${S.data.project.synthetic?'Illustrative data only.':''}</div></section><section class="card test-card"><div class="between"><span class="test-tag">OUR NEXT SMALL TEST</span>${badge('Plan','grey')}</div><h2 class="test-title">${esc(cycle?.title||'Choose a manageable first test')}</h2><p>${esc(cycle?.plan||'Agree a change, a prediction, and a way to learn.')}</p><div class="steps"><span></span><span></span><span></span><span></span></div><div class="between subtle"><span>Plan</span><span>Do</span><span>Study</span><span>Act</span></div><div class="test-meta between"><span class="subtle">${cycle?.status==='proposed'?'Proposed · not yet tested':esc(cycle?.status||'')}</span>${btn('Open worksheet '+icon('arrow'),'open-kind','quiet small','data-kind="pdsa"')}</div></section><section class="card"><div class="card-head"><div><h2>Where delays collect</h2><p>Category counts from the current validated snapshot</p></div>${badge('Pareto')}</div>${pareto(chart)}</section><section class="card"><div class="card-head"><div><h2>A little clarity for what’s next</h2><p>Suggested actions — confirm with the team</p></div></div>${actions.filter(a=>a.status!=='done').slice(0,3).map((a,i)=>`<div class="list-row"><span class="number">${i+1}</span><div><strong>${esc(a.text)}</strong><div class="meta">${esc(a.owner||'Unassigned')} ${a.due?'· '+esc(a.due):''}</div></div></div>`).join('')||'<div class="empty">No open actions.</div>'}<div class="mt">${btn('Review actions '+icon('arrow'),'open-kind','quiet small','data-kind="actions"')}</div></section></div><div class="footerline"><span>${icon('check')} Latest import: ${imported?esc(imported.status)+' · '+when(imported.created):'No import yet'}</span><span>${savedHome} · ${online()?'Companion connected':'OneDrive companion offline'}</span></div>`}
function graphSvg(body){const nodes=body.nodes||[],edges=body.edges||[];if(!nodes.length)return '<div class="empty">Add nodes and connections to build the diagram.</div>';const layers=new Map(nodes.map(n=>[n.id,0]));for(let pass=0;pass<nodes.length;pass++){let changed=false;for(const e of edges){if(layers.has(e.from)&&layers.has(e.to)&&layers.get(e.to)<Math.min(3,layers.get(e.from)+1)){layers.set(e.to,Math.min(3,layers.get(e.from)+1));changed=true}}if(!changed)break}const grouped=new Map();for(const n of nodes){const rank=layers.get(n.id);if(!grouped.has(rank))grouped.set(rank,[]);grouped.get(rank).push(n)}const columns=[...grouped.keys()].sort(),maxRows=Math.max(...[...grouped.values()].map(a=>a.length)),width=Math.max(260,columns.length*200),height=Math.max(140,maxRows*110+30),positions=new Map();columns.forEach((rank,col)=>grouped.get(rank).forEach((n,row)=>positions.set(n.id,{x:col*200+15,y:20+row*110})));return `<svg viewBox="0 0 ${width} ${height}" class="chart" role="img" aria-label="Editable structured relationship diagram"><defs><marker id="graph-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10" fill="#8ba280"/></marker></defs>${edges.map(e=>{const a=positions.get(e.from),b=positions.get(e.to);if(!a||!b)return '';return `<path d="M${a.x+165},${a.y+34} C${a.x+190},${a.y+34} ${b.x-20},${b.y+34} ${b.x},${b.y+34}" fill="none" stroke="#91aa84" stroke-width="1.5" marker-end="url(#graph-arrow)"/>`}).join('')}${nodes.map(n=>{const p=positions.get(n.id);const words=String(n.label||n.id).split(' ');const lines=[''];for(const word of words){if((lines.at(-1)+' '+word).length>23)lines.push(word);else lines[lines.length-1]+=(lines.at(-1)?' ':'')+word}return `<g><title>${esc(n.label)}</title><rect x="${p.x}" y="${p.y}" width="165" height="72" rx="8" fill="#f1f6ec" stroke="#cddcc2"/><text x="${p.x+82}" y="${p.y+17}" text-anchor="middle" style="font-size:8px;fill:#7d916e">${esc(n.type||n.id)}</text>${lines.slice(0,3).map((line,i)=>`<text x="${p.x+82}" y="${p.y+33+i*13}" text-anchor="middle" style="fill:#526c45;font-size:10px">${esc(line)}</text>`).join('')}</g>`}).join('')}</svg>`}
function diagram(a){const b=a.body;if(a.kind==='process'||a.kind==='drivers')return graphSvg(b);if(a.kind==='fishbone'){const causes=b.causes||[];return `<div class="notice">${esc(b.effect)} · Proposed causes are hypotheses, not established facts.</div><svg class="chart" viewBox="0 0 700 320" role="img" aria-label="Fishbone cause hypotheses"><line x1="20" y1="160" x2="560" y2="160" stroke="#77916a" stroke-width="2"/><path d="M548 153L560 160L548 167" fill="none" stroke="#77916a"/><rect x="566" y="126" width="128" height="69" rx="8" fill="#e9f1e0" stroke="#ceddc1"/><text x="630" y="152" text-anchor="middle" style="fill:#4e6a40">Effect to explore</text><text x="630" y="171" text-anchor="middle" style="font-size:8px">${esc(String(b.effect||'').slice(0,24))}</text>${causes.slice(0,6).map((c,i)=>{const x=55+Math.floor(i/2)*168,up=i%2===0;return `<path d="M${x},${up?45:275}L${x+72},160" stroke="#acbd9f" fill="none"/><text x="${x-20}" y="${up?30:300}" style="font-size:10px;fill:#667e57">${esc(c.category)}</text><foreignObject x="${x-15}" y="${up?55:218}" width="150" height="62"><div xmlns="http://www.w3.org/1999/xhtml" style="font-size:9px;line-height:1.6;color:#829477">${esc(c.text)}</div></foreignObject>`}).join('')}</svg><div class="fishbone">${causes.map(c=>`<div class="cause"><b>${esc(c.category)}</b><p>${esc(c.text)}</p>${badge(c.classification||'hypothesis','grey')}</div>`).join('')}</div>`}return ''}
const fieldPath=path=>esc(JSON.stringify(path));
function emptyItem(field){const id=crypto.randomUUID();return {nodes:{id,label:'New step',type:'secondary'},edges:{from:'',to:''},causes:{id,category:'Workflow',text:'',classification:'hypothesis',sources:[]},measures:{id,name:'',type:'outcome',operational_definition:'',population:'',unit_of_analysis:'',numerator:'',denominator:'',inclusion:'',exclusion:'',frequency:'',source:'',required_fields:[],owner:'Unassigned',burden:'',missing_data:'',validation:'',unintended_consequences:''},cycles:{id,title:'',status:'proposed',plan:'',prediction:'',do:'Not yet tested',study:'No observations yet',act:'',sources:[]},items:{id,text:'',classification:'ai_suggestion',status:'open',owner:'Unassigned',due:'',sources:[]},entries:{id,text:'',classification:'participant_statement',sources:[]},sources:{type:'transcript',meeting:'',segment:'',revision:1},required_fields:''}[field]??{id,text:''}}

function fields(value,path=[]){if(Array.isArray(value))return `<div class="record">${value.map((v,i)=>`<div class="record"><div class="record-head"><span class="eyebrow">${esc(title(String(path.at(-1)||'Item')))} ${i+1}</span>${btn('Remove','remove-item','quiet small danger',`data-path="${fieldPath([...path,i])}"`)}</div>${fields(v,[...path,i])}</div>`).join('')}${btn(icon('plus')+'Add '+esc(title(String(path.at(-1)||'item'))),'add-item','small',`data-path="${fieldPath(path)}"`)}</div>`;
if(value!==null&&typeof value==='object')return Object.entries(value).map(([key,v])=>{const p=[...path,key];if(['id','segment','speaker'].includes(key))return `<div class="proof">${title(key)}: ${esc(v)}</div>`;if(key==='sources')return `<details><summary>Source links (${Array.isArray(v)?v.length:0})</summary>${sources(v)}<details><summary>Edit source records</summary>${fields(v,p)}</details></details>`;if(typeof v==='object'&&v!==null)return `<div class="field"><label>${esc(title(key))}</label>${fields(v,p)}</div>`;return `<div class="field"><label>${esc(title(key))}${key==='classification'?' · preserve statement / hypothesis / decision distinction':''}</label>${typeof v==='boolean'?`<input type="checkbox" data-field="${fieldPath(p)}" ${v?'checked':''}>`:typeof v==='number'?`<input type="number" data-field="${fieldPath(p)}" value="${v}">`:`<textarea rows="${String(v||'').length>130?3:2}" data-field="${fieldPath(p)}">${esc(v)}</textarea>`}</div>`}).join('');return `<input data-field="${fieldPath(path)}" value="${esc(value)}">`}
function sources(items){return (items||[]).map(s=>s.type==='transcript'?btn('Transcript · '+esc(s.segment),'source','inline-link',`data-meeting="${esc(s.meeting)}" data-segment="${esc(s.segment)}"`):s.document?`<a class="source" href="${url('/references/'+encodeURIComponent(s.document)+'/file')}#page=${s.pdf_index+1}" target="_blank" rel="noopener">${esc(s.title)} · PDF page ${s.pdf_index+1}${s.printed_page?' · printed label '+esc(s.printed_page):''}${s.quote?'<br>“'+esc(s.quote)+'”':''}</a>`:`<span class="proof">${esc(JSON.stringify(s))}</span>`).join(' ')}
function docs(){const all=S.data.artifacts.filter(a=>a.kind!=='suggestions');if(!S.doc||!all.some(a=>a.id===S.doc))S.doc=all.find(a=>a.kind==='charter')?.id||all[0]?.id;const a=all.find(a=>a.id===S.doc);if(a&&!S.dirty&&!S.saving){S.draft=structuredClone(a.body);S.editRevision=a.revision}return heading('A shared understanding, always current.','Editable records with source links, version history, and protected manual changes.',btn('Print / save PDF','print')+btn(icon('plus')+'New document','new-doc','primary'))+`<div class="docs-layout"><div class="document-list">${all.map(d=>btn(`<span>${esc(d.title)}<small>Revision ${d.revision} · ${esc(d.kind)}</small></span>`,'select-doc',d.id===S.doc?'active':'',`data-id="${esc(d.id)}"`)).join('')}</div>${a?`<section class="card document-editor"><div class="card-head"><div><h2>${esc(a.title)}</h2><p>${esc(a.author)} · ${when(a.updated)}</p></div><div><div id="saveState" class="save-state">${S.dirty?'Unsaved draft':'✓ '+savedHome+' · revision '+a.revision}</div><div class="toolbar">${btn('History & undo','history','small')}${btn('Save now','save-doc','small')}</div></div></div><div id="diagram">${diagram({...a,body:S.draft})}</div><div id="fields">${fields(S.draft)}</div><p class="proof">Changes autosave. Suggestions remain suggestions; only a human can confirm a team decision.</p></section>`:'<div class="empty">Create your first document.</div>'}</div>`}
function bindEditor(){$$('#fields [data-field]').forEach(el=>el.addEventListener('input',()=>{setAt(S.draft,JSON.parse(el.dataset.field),el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value);S.dirty=true;$('#saveState').textContent='Saving shortly…';clearTimeout(S.timer);S.timer=setTimeout(saveDoc,1000)}))}
function setAt(obj,path,value){const last=path.at(-1);let node=obj;for(const k of path.slice(0,-1))node=node[k];node[last]=value}
function getAt(obj,path){return path.reduce((v,k)=>v[k],obj)}
async function saveDoc(){if(!S.dirty||S.saving)return;S.saving=true;const snapshot=JSON.stringify(S.draft),id=S.doc;try{const r=await api(url('/artifacts/'+id),'PUT',{revision:S.editRevision,body:JSON.parse(snapshot)});S.editRevision=r.revision;S.dirty=JSON.stringify(S.draft)!==snapshot;const a=S.data.artifacts.find(x=>x.id===id);if(a){a.revision=r.revision;a.body=JSON.parse(snapshot)}const status=$('#saveState');if(status)status.textContent='✓ '+savedHome+' · revision '+r.revision;const dg=$('#diagram');if(dg&&a)dg.innerHTML=diagram({...a,body:S.draft});if(S.dirty)S.timer=setTimeout(saveDoc,400)}catch(e){if(e.status===409){S.conflict=e.data.current;modal('Your draft is safe',`<p class="subtle">Another change was saved first. Compare both versions before choosing what to keep.</p><div class="grid equal"><div><h3>Your draft</h3><pre>${esc(JSON.stringify(S.draft,null,2))}</pre></div><div><h3>Latest saved version</h3><pre>${esc(JSON.stringify(S.conflict.body,null,2))}</pre></div></div>`,btn('Keep editing my draft','close-modal')+btn('Use saved version','use-saved')+btn('Save my draft over this version','keep-draft','primary'))}else toast(e.message);const state=$('#saveState');if(state)state.textContent='Not saved · draft preserved'}finally{S.saving=false}}
function dataView(){const datasets=S.data.datasets;return heading('Good decisions start with useful data.','Complete, dated snapshots. Deterministic calculations. A traceable history.',btn(icon('plus')+'Define a dataset','new-dataset','primary'))+`<div class="grid"><section class="card"><div class="card-head"><div><h2>Bring in a new snapshot</h2><p>CSV or XLSX · maximum 25 MB · MRNs preserved as strings</p></div></div><form id="importForm"><div class="field"><label for="dataset">Dataset mapping</label><select id="dataset" name="dataset">${datasets.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select></div><div class="grid equal"><div class="field"><label for="effective">Dataset as-of date</label><input required type="date" id="effective" name="effective"></div><div class="field"><label for="sequence">Correction sequence</label><input type="number" id="sequence" name="sequence" value="0" min="0"></div></div><div class="field"><label for="snapshot">Complete snapshot file</label><input required type="file" id="snapshot" name="file" accept=".csv,.xlsx"></div><button class="primary" type="submit">${icon('plus')}Validate & import</button></form><div class="notice">The latest validated as-of date and correction sequence determine current results. Arrival order does not. Invalid files preserve the last valid charts.</div></section><section class="card"><div class="card-head"><div><h2>Measurement definitions</h2><p>Versioned mappings, operational definitions, and lineage</p></div></div>${datasets.map(d=>`<div class="list-row"><div><h3>${esc(d.name)}</h3><p class="subtle">${esc(d.spec.aggregation)} · ${esc(d.spec.unit)} · definition ${d.revision}</p><p class="proof">${esc(d.spec.unit_of_analysis||'Unit of analysis needs definition')} · ${esc(d.id)}</p><div class="toolbar">${btn('Edit mapping','edit-mapping','small',`data-id="${esc(d.id)}"`)}${btn('Plan','open-kind','small','data-kind="measurement"')}</div></div></div>`).join('')}</section></div><section class="card mt"><div class="card-head"><div><h2>Snapshot history</h2><p>Each original and validation report is retained in the project export.</p></div></div><div class="table-wrap"><table><thead><tr><th>File</th><th>As-of / correction</th><th>Result</th><th>Records</th><th>Imported</th><th></th></tr></thead><tbody>${S.data.imports.map(i=>`<tr><td>${esc(i.filename)}${datasets.some(d=>d.current_import===i.id)?' '+badge('Current'):''}</td><td>${esc(i.effective)} / ${i.sequence}</td><td>${badge(i.status,i.status==='failed'?'red':'')}</td><td>${i.report.record_count??'—'}</td><td>${when(i.created)}</td><td>${btn('Report','import-report','small',`data-id="${i.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`}
function replies(){return S.data.jobs.filter(j=>['coach','interjection'].includes(j.kind)).slice(0,6).map(j=>`<div class="reply"><div class="between"><span class="eyebrow">QI COACH</span>${badge(j.status,j.status==='failed'?'red':'grey')}</div>${j.result?.answer?`<p class="mt">${esc(j.result.answer)}</p>${sources(j.result.citations)}${j.result.document_changes?.length?'<div class="notice">Saved '+j.result.document_changes.length+' document update(s). Inspect QI documents and version history.</div>':''}${j.result.rejected_updates?.length?'<div class="notice">Some edits were rejected: '+esc(j.result.rejected_updates.join('; '))+'</div>':''}<div class="subtle">${esc(j.result.basis)} · ${j.result.latency_seconds}s${j.result.model?' · '+esc(j.result.model):''}</div>`:`<p class="mt">${esc(j.result?.message||j.error||(j.status==='cancelled'?'Reply cancelled.':j.status==='stale'?'Project changed; please ask again.':'Checking the current project state and available references…'))}</p>`}${['queued','running'].includes(j.status)?btn('Cancel reply','cancel-job','quiet small',`data-id="${j.id}"`):''}</div>`).join('')}
function meetings(){const m=S.data.meetings.find(m=>m.id===S.meeting),md=S.meetingData,config=m?JSON.parse(m.config):{},speakers=md?.speakers||[];return heading('Make space for the conversation.','QI Coach listens when enabled, stays engaged when addressed, and keeps the record clear.',btn('New session','new-meeting')+btn('Replay synthetic meeting','replay','primary'))+`<div class="grid"><div><section class="card"><div class="between"><div class="inline"><div class="mic-circle ${m?.state==='listening'?'pulse':''}">${icon('meetings')}</div><div><h2>${esc(config.agent_name||'QI Coach')}</h2><p class="subtle">${esc(title(m?.state||'paused'))} · ${audioOnline()?'Windows audio connected':'Audio companion offline'}</p></div></div>${btn('Settings','meeting-settings','small')}</div><div class="meeting-controls">${btn('Listen','state',m?.state==='listening'?'primary':'','data-state="listening"')}${btn('Engage','state',m?.state==='engaged'?'primary':'','data-state="engaged"')}${btn('Stop speaking','state','','data-state="engaged"')}${btn('Pause','state',m?.state==='paused'?'primary':'','data-state="paused"')}</div><p class="proof">Audio requires the Windows companion. Screen sharing does not supply meeting audio. Raw audio retention: ${S.data.retention.raw_audio_hours} hours. Transcript retention: ${S.data.retention.transcript_days} days.</p><div class="field"><label for="meetingSelect">Working session</label><select id="meetingSelect">${S.data.meetings.map(x=>`<option value="${x.id}" ${x.id===S.meeting?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="transcript">${(md?.segments||[]).slice().reverse().map(s=>{const speaker=speakers.find(p=>p.id===s.speaker);return `<div class="segment" id="segment-${s.id}"><div class="speaker">${esc(speaker?.label||s.speaker)} ${speaker?.verified?badge('Verified'):badge('Unverified','grey')} ${s.overlap?badge('Overlap','amber'):''} ${s.uncertain?'<span>Attribution uncertain</span>':''}</div><p>${esc(s.text)}</p><div class="between"><span class="proof">Revision ${s.revision} · ${s.final?'Final segment':'Partial'}</span><div class="inline">${btn('Correct','correct-segment','inline-link',`data-id="${s.id}"`)}${btn('Record team decision','confirm-decision','inline-link',`data-id="${s.id}"`)}</div></div></div>`}).join('')||'<div class="empty">The room is ready.<br>Start listening and replay a synthetic session, or connect the Windows audio companion.</div>'}</div><form id="segmentForm" class="composer"><label class="screen-reader" for="segmentText">Transcript text</label><textarea id="segmentText" name="text" required placeholder="Enter a statement or say: QI Coach, help us with this."></textarea><button type="submit">Add segment</button></form><div class="toolbar">${btn('Correct speaker labels','speakers','small')}</div></section><section class="card"><h2>Coaching checks</h2><p class="subtle">Only concrete gaps relevant to a pending decision, after a pause.</p>${(md?.issues||[]).map(i=>`<div class="list-row"><div><strong>${esc(title(i.issue.replaceAll('-',' ')))}</strong><div class="meta">${esc(i.status)}</div></div><div class="push inline">${btn('Defer','defer','small',`data-issue="${i.issue}" data-status="deferred"`)}${btn('Dismiss','defer','small',`data-issue="${i.issue}" data-status="dismissed"`)}</div></div>`).join('')||'<p class="proof mt">No coaching checks raised.</p>'}</section></div><section class="card"><div class="card-head"><div><h2>A thought partner for your team</h2><p>Grounded in your project. Clear about missing evidence.</p></div>${badge('Local inference')}</div><form id="coachForm"><label class="screen-reader" for="coachPrompt">Ask QI Coach</label><textarea id="coachPrompt" name="prompt" required placeholder="What should we do next, and what information is missing?"></textarea><div class="between mt"><select id="modelRoute" aria-label="Model route"><option value="reasoning">Qwen 3.8 · 27B</option><option value="fast">Qwen 3.5 · 9B</option></select><button class="primary" type="submit">Ask QI Coach ${icon('arrow')}</button></div></form>${replies()}<p class="proof mt">Suggestions do not become team decisions automatically. Clinical or methodological expertise still requires review.</p></section></div>`}
function library(){return heading('Make the evidence inspectable.','An authorized, project-specific reference library. Every citation leads back to a page.')+`<div class="grid"><section class="card"><h2>Add an authorized reference</h2><form id="referenceForm"><div class="field"><label for="refTitle">Document title</label><input id="refTitle" name="title" required placeholder="Title from the original publication"></div><div class="grid equal"><div class="field"><label for="refEdition">Edition / version</label><input id="refEdition" name="edition" placeholder="As stated in the document"></div><div class="field"><label for="refPriority">Source priority (lower first)</label><input id="refPriority" type="number" name="priority" value="10"></div></div><div class="field"><label for="refFile">Authorized PDF</label><input id="refFile" type="file" name="file" accept=".pdf" required></div><div class="field"><label><input type="checkbox" name="ocr" value="true"> OCR scanned pages (requires local OCR utilities)</label></div><button class="primary" type="submit">Add to project library</button></form><div class="notice">PDF index and printed page labels are recorded separately. Missing labels and extraction failures are shown explicitly.</div></section><section class="card"><h2>Find supporting passages</h2><form id="searchForm" class="composer"><input name="q" aria-label="Search references" required placeholder="e.g. balancing measures"><button type="submit">Search</button></form><div id="searchResults" class="search-results"><p class="proof">Retrieval searches only this project's library. No source means no supported citation.</p></div></section></div><section class="card mt"><h2>Project references</h2>${S.data.references.map(r=>`<div class="list-row"><div><h3>${esc(r.title)}</h3><p class="subtle">${esc(r.edition||'Edition not supplied')} · priority ${r.priority} · ${esc(r.status)}</p><p class="proof">${esc(JSON.parse(r.report).chunks)} extracted passages · ${JSON.parse(r.report).failures.length} page failures</p></div><a class="button small push" href="${url('/references/'+r.id+'/file')}" target="_blank" rel="noopener">Inspect PDF</a>${btn('Report','reference-report','small',`data-id="${r.id}"`)}</div>`).join('')||'<div class="empty">No textbooks selected yet.<br>Add only material authorized for this project.</div>'}${S.data.jobs.filter(j=>j.kind==='pdf').map(j=>`<div class="list-row">PDF ingestion ${badge(j.status,j.status==='failed'?'red':'grey')}<span class="proof">${esc(j.error||'')}</span></div>`).join('')}</section>`}
function delivery(){const pending=S.data.transfer_counts?.saved_on_spark||0;return heading('Keep the work organized and recoverable.','Consistent backups and portable project folders, delivered through your Windows companion.',btn('Create backup','export','','data-kind="backup"')+btn(icon('delivery')+'Export project','export','primary','data-kind="export"'))+`<div class="stats"><div class="stat"><div class="label">Spark workspace</div><div class="value" style="font-size:23px">Saved locally</div><div class="subtle">Database stays on Spark</div></div><div class="stat"><div class="label">Windows companion</div><div class="value" style="font-size:23px">${online()?'Connected':'Offline'}</div><div class="subtle">Last contact: ${when(S.data.companion?.last_contact)}</div></div><div class="stat"><div class="label">Pending delivery</div><div class="value">${pending}<span>transfers</span></div><div class="subtle">Cloud synchronization is unverified</div></div></div><div class="notice">“Delivered locally” confirms an integrity-checked file in the designated OneDrive folder. It does not confirm OneDrive cloud synchronization. Existing external edits are preserved as conflicts.</div><section class="card"><h2>Transfer queue</h2><div class="table-wrap"><table><thead><tr><th>Artifact</th><th>Status</th><th>Created</th><th>Delivered</th><th></th></tr></thead><tbody>${S.data.transfers.map(t=>`<tr><td>${esc(t.path)}</td><td>${badge(t.status==='delivered_local'?'Delivered locally':'Saved on Spark',t.status==='delivered_local'?'':'amber')}</td><td>${when(t.created)}</td><td>${when(t.delivered)}</td><td><a class="button small" href="${url('/transfers/'+t.id+'/file')}">Download</a></td></tr>`).join('')}</tbody></table></div>${!S.data.transfers.length?'<div class="empty">Create an export or backup to start the transfer queue.</div>':''}</section><section class="card"><h2>Background work</h2>${S.data.jobs.filter(j=>['export','backup'].includes(j.kind)).map(j=>`<div class="list-row"><span>${esc(title(j.kind))}</span>${badge(j.status,j.status==='failed'?'red':'grey')}<span class="proof">${esc(j.error||'')}</span></div>`).join('')||'<p class="subtle mt">No export or backup jobs yet.</p>'}</section><section class="card"><h2>Ready for Windows 10</h2><div class="toolbar"><a class="button" href="${url('/companion-package')}">Download Windows package</a>${S.role==='owner'?btn('Create companion key','companion-key','primary'):''}</div><p class="subtle mt">Companion setup and audio routing instructions are in the project’s <strong>docs/WINDOWS_COMPANION.md</strong>. Pin the designated folder with OneDrive’s “Always keep on this device.” A separate companion credential limits access to this project.</p></section>`}
function pilot(){return heading('Learn whether the assistant helps.','Software correctness and QI expertise are evaluated separately.')+`<div class="grid"><section class="card"><h2>Record a pilot observation</h2><p class="subtle mt">Use measured values, not estimated targets.</p><form id="metricForm"><div class="field"><label for="metricKind">Metric</label><select id="metricKind" name="kind"><option value="confidence_1_5">User confidence (1–5)</option><option value="correction_seconds">Document correction time (seconds)</option><option value="unwanted_interruption">Unwanted interruptions (count)</option><option value="time_saved_minutes">Time saved (minutes)</option><option value="retrieval_relevant">Relevant retrieval (0 or 1)</option><option value="citation_correct">Correct citation (0 or 1)</option><option value="speaker_correct">Correct speaker attribution (0 or 1)</option><option value="transcription_wer">Transcription word error rate (0–1)</option></select></div><div class="field"><label for="metricValue">Observed value</label><input id="metricValue" type="number" step="any" name="value" required></div><button class="primary" type="submit">Record observation</button></form></section><section class="card"><h2>Review with a QI expert</h2><div class="list-row"><span class="number">1</span><div>Check whether the next actions fit the team's context and available evidence.</div></div><div class="list-row"><span class="number">2</span><div>Review measure definitions, missing-data decisions, chart interpretation, and unintended effects.</div></div><div class="list-row"><span class="number">3</span><div>Score citations, speaker corrections, and unwanted interruptions in an actual meeting.</div></div><div class="notice">Windows Teams audio and OneDrive cloud synchronization require end-to-end validation on the user's computer. Passing automated tests is not validation of methodological expertise.</div></section></div><section class="card mt"><div class="between"><h2>Measured observations</h2>${btn('Refresh measurements','load-metrics','small')}</div><div id="metricsResults" class="mt"><p class="subtle">Load the project's recorded observations and model / transcription timings.</p></div></section>`}
function modal(name,body,actions=btn('Close','close-modal')){$('#modal').innerHTML=`<h2>${esc(name)}</h2>${body}<div class="actions">${actions}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function login(error=''){$('#app').innerHTML=`<div class="login"><div class="login-art"><div class="brand"><span class="brandmark">✳</span>QI Coach</div><h1>Better care starts with a shared understanding.</h1><p>A thoughtful workspace for your team’s next small step in quality improvement.</p></div><div class="login-form"><form id="loginForm" class="login-box"><div class="eyebrow">PRIVATE SPARK WORKSPACE</div><h2 style="font-size:27px;margin-top:14px">Welcome to your project.</h2><p>Sign in with the project access key issued on your Spark. Your session stays private to this browser.</p><label class="subtle" for="accessKey">Project access key</label><input id="accessKey" name="token" type="password" autocomplete="off" required placeholder="Paste your access key"><button type="submit" class="primary">Open workspace ${icon('arrow')}</button><div class="error-text">${esc(error)}</div><p class="proof">First setup: the owner access key is saved in the private runtime/owner.token file on Spark. Use a separate project-scoped key for each teammate.</p></form></div></div>`}
async function boot(){try{const me=await api('/api/me');S.project=me.project;S.role=me.role;await refresh(true);startEvents()}catch(e){login(e.status===401?'':e.message)}}

document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;try{
if(action==='close-modal')return $('#modal').close();
if(action==='nav'){await saveDoc();if(S.dirty)return toast('Resolve the current draft before changing pages.');S.page=el.dataset.page;if(S.page==='meetings'&&S.meeting)S.meetingData=await api(url('/meetings/'+S.meeting));render();return}
if(action==='logout'){await api('/api/logout','POST',{});S.events?.close();S.data=null;S.project=null;login();return}
if(action==='print')return window.print();
if(action==='open-kind'){const a=art(el.dataset.kind);if(!a)return toast('No document of this type yet.');await saveDoc();if(S.dirty)return toast('Resolve the current draft first.');S.page='docs';S.doc=a.id;S.dirty=false;render();return}
if(action==='select-doc'){await saveDoc();if(S.dirty)return toast('Save or resolve the current draft first.');S.doc=el.dataset.id;render();return}
if(action==='save-doc')return await saveDoc();
if(action==='add-item'||action==='remove-item'){const path=JSON.parse(el.dataset.path);if(action==='remove-item')getAt(S.draft,path.slice(0,-1)).splice(path.at(-1),1);else{const arr=getAt(S.draft,path);const sample=arr[0];function blank(v){if(Array.isArray(v))return [];if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,k==='id'?crypto.randomUUID():k==='classification'?'hypothesis':blank(x)]));return typeof v==='boolean'?false:typeof v==='number'?0:''}arr.push(sample===undefined?emptyItem(path.at(-1)):blank(sample))}S.dirty=true;render();clearTimeout(S.timer);S.timer=setTimeout(saveDoc,2500);return}
if(action==='use-saved'){S.draft=structuredClone(S.conflict.body);S.editRevision=S.conflict.revision;S.dirty=false;S.data.artifacts=S.data.artifacts.map(a=>a.id===S.doc?S.conflict:a);$('#modal').close();render();return}
if(action==='keep-draft'){S.editRevision=S.conflict.revision;$('#modal').close();await saveDoc();return}
if(action==='history'){const versions=await api(url('/artifacts/'+S.doc+'/versions'));modal('Document history',versions.map(v=>`<div class="list-row"><div><h3>Revision ${v.revision}</h3><p class="subtle">${esc(v.author)} · ${when(v.created)} · ${esc(v.reason)}</p><details><summary>Inspect content</summary><pre>${esc(JSON.stringify(v.body,null,2))}</pre></details></div>${btn('Restore','restore-version','small push',`data-revision="${v.revision}"`)}</div>`).join(''));return}
if(action==='restore-version'){await api(url('/artifacts/'+S.doc+'/undo'),'POST',{revision:S.editRevision,target_revision:Number(el.dataset.revision)});S.dirty=false;$('#modal').close();await refresh(true);toast('Restored as a new revision. History preserved.');return}
if(action==='new-doc'){modal('Create a QI document',`<form id="newDocForm"><div class="field"><label>Document type</label><select name="kind">${['charter','process','fishbone','drivers','measurement','pdsa','notes','decisions','actions','questions'].map(k=>`<option value="${k}">${title(k)}</option>`).join('')}</select></div><div class="field"><label>Title</label><input name="title" required></div><button class="primary" type="submit">Create document</button></form>`);return}
if(action==='edit-mapping'||action==='new-dataset'){const d=S.data.datasets.find(d=>d.id===el.dataset.id);S.mappingId=d?.id;modal(d?'Edit dataset definition':'Define a dataset',`<form id="mappingForm"><div class="field"><label>Dataset name</label><input name="name" value="${esc(d?.name||'')}" required></div><p class="subtle">Use actual supplied column names. Complete snapshots only; choose a stable encounter key. Mapping changes are validated against the current snapshot before saving.</p><textarea class="json-editor mt" name="spec">${esc(JSON.stringify(d?.spec||{policy:'snapshot',mapping:{key:'encounter_id',date:'date',value:'value',category:'category',mrn:'mrn'},aggregation:'mean',unit:'minutes',minimum:0,baseline_points:10,unit_of_analysis:'Encounter'},null,2))}</textarea><button class="primary mt" type="submit">Validate & save definition</button></form>`);return}
if(action==='import-report'){const i=S.data.imports.find(i=>i.id===el.dataset.id);modal('Validation report',`<pre>${esc(JSON.stringify(i.report,null,2))}</pre>`);return}
if(action==='reference-report'){const r=S.data.references.find(r=>r.id===el.dataset.id);modal('Extraction report',`<pre>${esc(JSON.stringify(JSON.parse(r.report),null,2))}</pre>`);return}
if(action==='new-meeting'){modal('Start a working session',`<form id="meetingForm"><div class="field"><label>Session name</label><input name="name" required placeholder="QI working session"></div><button class="primary" type="submit">Create session</button></form>`);return}
if(action==='state'){if(!S.meeting)return toast('Create a meeting first.');await api(url('/meetings/'+S.meeting+'/state'),'POST',{state:el.dataset.state});await refresh(true);return}
if(action==='replay'){if(!S.data.project.synthetic)return toast('Synthetic replay is restricted to the demonstration project.');el.disabled=true;await api(url('/meetings/'+S.meeting+'/state'),'POST',{state:'listening'});const events=[{id:'replay-01',text:'Maybe room readiness is contributing to the delays.',voice:'1'},{id:'replay-02',text:'Let us try a small morning huddle and learn before expanding.',voice:'2'},{id:'replay-03',text:'The balancing measure still needs a clear definition.',voice:'1'},{id:'replay-04',text:'We should confirm the test owner with the team.',voice:'unassigned'},{id:'replay-02',revision:2,text:'Correction: the huddle is only a proposal. We have not agreed to run it.',voice:'2'}];for(const e of events)await api(url('/meetings/'+S.meeting+'/segments'),'POST',{source:'room',uncertain:true,...e});await refresh(true);toast('Synthetic statements and a correction replayed. No decisions were inferred.');return}
if(action==='correct-segment'){const s=S.meetingData.segments.find(s=>s.id===el.dataset.id);S.segmentEdit=s;modal('Correct transcript segment',`<form id="correctForm"><textarea name="text" required>${esc(s.text)}</textarea><div class="field"><label>Voice label within this source (e.g. 1 or 2; not a verified name)</label><input name="voice" value="${esc(s.speaker.split(':')[1])}" pattern="[a-zA-Z0-9_-]{1,40}"></div><button class="primary mt" type="submit">Save correction</button></form>`);return}
if(action==='confirm-decision'){const s=S.meetingData.segments.find(s=>s.id===el.dataset.id);S.decisionSegment=s;modal('Record a confirmed team decision',`<p class="subtle">Only use this when the team has explicitly agreed. This records your confirmation and links the transcript; a brainstorming statement alone is not agreement.</p><form id="decisionForm"><div class="field"><label>Agreed decision</label><textarea name="text" required>${esc(s.text)}</textarea></div><div class="field"><label>Rationale</label><textarea name="rationale" required></textarea></div><button class="primary" type="submit">Confirm team agreement & record</button></form>`);return}
if(action==='source'){const md=await api(url('/meetings/'+encodeURIComponent(el.dataset.meeting)));const segment=md.segments.find(s=>s.id===el.dataset.segment);modal('Transcript evidence',segment?`<p class="subtle">Revision ${segment.revision} · ${segment.uncertain?'Attribution uncertain':'Attribution supplied'}</p><pre>${esc(segment.text)}</pre>`:'<p>Source is outside the recent 300 segments or has expired. Inspect the project export.</p>');return}
if(action==='speakers'){modal('Meeting-scoped speaker labels',`<p class="subtle">Source, voice, and verified identity are separate. Correct a label only when the team can verify it; labels do not carry into another meeting.</p>${(S.meetingData?.speakers||[]).map(s=>`<form class="speakerForm" data-id="${esc(s.id)}"><div class="field"><label>${esc(s.source)} / ${esc(s.voice)}</label><input name="label" value="${esc(s.label)}" required></div><label class="subtle"><input type="checkbox" name="verified" ${s.verified?'checked':''}> Identity verified by a participant</label><button class="small" type="submit">Save label</button></form>`).join('')}`);return}
if(action==='meeting-settings'){const m=S.data.meetings.find(m=>m.id===S.meeting),c=JSON.parse(m.config);modal('Meeting behavior',`<form id="meetingSettings"><div class="field"><label>Agent name</label><input name="agent_name" value="${esc(c.agent_name)}" required></div><div class="field"><label>Coaching sensitivity</label><select name="coaching">${['off','low','medium'].map(x=>`<option ${x===c.coaching?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Cooldown seconds</label><input type="number" name="cooldown_seconds" min="60" value="${c.cooldown_seconds}"></div><div class="field"><label>Suitable pause in seconds</label><input type="number" name="pause_seconds" min="2" value="${c.pause_seconds}"></div><button type="submit" class="primary">Save behavior</button></form>`);return}
if(action==='defer'){await api(url(`/meetings/${S.meeting}/issues/${el.dataset.issue}`),'POST',{status:el.dataset.status});await refresh(true);return}
if(action==='cancel-job'){await api(url('/jobs/'+el.dataset.id+'/cancel'),'POST',{});await refresh(true);return}
if(action==='export'){const r=await api(url('/exports'),'POST',{kind:el.dataset.kind,request_id:crypto.randomUUID()});toast('Queued on Spark. You can keep working.');await refresh(true);return}
if(action==='companion-key'){const r=await api(url('/companion-key'),'POST',{});const blob=new Blob([r.token+'\n'],{type:'text/plain'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='companion.token';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Companion key downloaded. Store it in the private Windows companion directory.');return}
if(action==='load-metrics'){const rows=await api(url('/metrics'));$('#metricsResults').innerHTML=rows.length?`<table><thead><tr><th>Metric</th><th>Value</th><th>Recorded</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(title(r.kind))}</td><td>${num(r.value)}</td><td>${when(r.created)}</td></tr>`).join('')}</tbody></table>`:'<p class="subtle">No measurements recorded yet.</p>';return}
}catch(e){toast(e.message)}finally{el.disabled=false}});

document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,f=new FormData(form),obj=Object.fromEntries(f),submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
if(form.id==='loginForm'){const r=await api('/api/login','POST',obj);S.project=r.project;S.role=r.role;await refresh(true);startEvents();return}
if(form.id==='importForm'){toast('Validating snapshot…');const r=await api(url('/imports'),'POST',f);await refresh(true);toast(r.status==='validated'?'Snapshot validated. Charts refreshed from the latest ordered snapshot.':'Import failed; last valid charts retained. Open the validation report.');return}
if(form.id==='mappingForm'){const spec=JSON.parse(obj.spec);if(S.mappingId){const d=S.data.datasets.find(d=>d.id===S.mappingId);await api(url('/datasets/'+d.id),'PUT',{revision:d.revision,body:spec})}else await api(url('/datasets'),'POST',{name:obj.name,spec});$('#modal').close();await refresh(true);return}
if(form.id==='newDocForm'){const existing=art(obj.kind);const body=existing?structuredClone(existing.body):{items:[]};function clear(v){if(Array.isArray(v))return [];if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,clear(x)]));return ''}const r=await api(url('/artifacts'),'POST',{...obj,body:clear(body)});S.doc=r.id;S.dirty=false;$('#modal').close();await refresh(true);return}
if(form.id==='meetingForm'){const r=await api(url('/meetings'),'POST',obj);S.meeting=r.id;$('#modal').close();await refresh(true);return}
if(form.id==='segmentForm'){const r=await api(url('/meetings/'+S.meeting+'/segments'),'POST',{id:crypto.randomUUID(),text:obj.text,uncertain:true});if(r.ignored)toast('Segment not captured: '+r.ignored);else form.reset();await refresh(true);return}
if(form.id==='coachForm'){await api(url('/coach'),'POST',{prompt:obj.prompt,route:$('#modelRoute').value,meeting:S.meeting,request_id:crypto.randomUUID()});form.reset();await refresh(true);return}
if(form.id==='correctForm'){const s=S.segmentEdit;await api(url('/meetings/'+S.meeting+'/segments'),'POST',{id:s.id,revision:s.revision+1,text:obj.text,source:s.speaker.split(':')[0],voice:obj.voice||s.speaker.split(':')[1],uncertain:Boolean(s.uncertain),overlap:Boolean(s.overlap)});$('#modal').close();await refresh(true);return}
if(form.id==='decisionForm'){let a=art('decisions');if(!a){await api(url('/artifacts'),'POST',{kind:'decisions',title:'Confirmed decisions',body:{items:[]}});await refresh();a=art('decisions')}const body=structuredClone(a.body);body.items.push({id:crypto.randomUUID(),text:obj.text,rationale:obj.rationale,classification:'confirmed_team_decision',confirmed_by:'Human workspace editor',sources:[{type:'transcript',meeting:S.meeting,segment:S.decisionSegment.id,revision:S.decisionSegment.revision}]});await api(url('/artifacts/'+a.id),'PUT',{revision:a.revision,body});$('#modal').close();await refresh(true);toast('Team decision recorded with your confirmation.');return}
if(form.classList.contains('speakerForm')){await api(url('/meetings/'+S.meeting+'/speakers'),'PUT',{id:form.dataset.id,label:obj.label,verified:f.has('verified')});toast('Speaker label corrected across this meeting’s records.');return}
if(form.id==='meetingSettings'){await api(url('/meetings/'+S.meeting+'/config'),'PUT',{...obj,cooldown_seconds:Number(obj.cooldown_seconds),pause_seconds:Number(obj.pause_seconds)});$('#modal').close();await refresh(true);return}
if(form.id==='referenceForm'){await api(url('/references'),'POST',f);form.reset();await refresh(true);toast('Reference ingestion queued. Extraction failures will be reported.');return}
if(form.id==='searchForm'){const rows=await api(url('/references/search?q='+encodeURIComponent(obj.q)));$('#searchResults').innerHTML=rows.map(r=>`<div class="reply"><h3>${esc(r.title)}</h3><p class="subtle">${esc(r.edition)} · PDF page ${r.pdf_index+1} · printed label ${esc(r.printed_page||'unknown')}</p><p class="mt">${esc(r.text)}</p><a class="button small mt" href="${url('/references/'+r.doc+'/file')}#page=${r.pdf_index+1}" target="_blank" rel="noopener">Inspect source page</a></div>`).join('')||'<div class="empty">No matching evidence found. No citation can be supplied.</div>';return}
if(form.id==='metricForm'){await api(url('/metrics'),'POST',{kind:obj.kind,value:Number(obj.value)});form.reset();toast('Measured observation recorded.');return}
}catch(e){if(form.id==='loginForm')login(e.message);else toast(e.message)}finally{if(submit)submit.disabled=false}});
document.addEventListener('change',async e=>{if(e.target.id==='meetingSelect'){S.meeting=e.target.value;S.meetingData=await api(url('/meetings/'+S.meeting));render()}});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue=''}});
boot();
